# -*- coding: utf-8 -*-
"""깨우는 일이 **정말 돌고 있는지** 자취를 보고 가린다 (1119, 1120 고침).

    python .github/scripts/check_keep_awake.py runs.json

왜 필요한가
    깃허브 예약은 늦거나 **통째로 건너뜁니다.** 그런데 돌지 않은 일은 실패도
    아니라서 아무 알림이 오지 않습니다 — 조용히 비어 있습니다. 1119 에
    6시간 예약이 한 번도 안 돈 채 17시간이 지나 있었는데, 손으로 돌리고
    사이트를 두드려 대느라 아무도 몰랐습니다.

1120 — 이제 **일러바치지 않고 고칩니다**
    전에는 빈틈을 보면 일부러 실패해서 메일을 보냈습니다. 메일은 알려 줄 뿐
    고치지는 못합니다. 사람이 읽고 손으로 눌러야 하는데, 자는 동안에는 아무도
    안 읽습니다. 그래서 이제 이 일이 **스스로 깨웁니다.**

      · 마지막으로 깨운 지 8시간이 넘었다  → 지금 깨운다 (돌려주는 값 10)
      · 12시간이 넘었다                   → 깨우고 **메일도 보낸다** (값 10 + 위험)
      · 그 밖에 자취가 아예 없다           → 실패 (값 1)

    스트림릿이 재우는 기준이 12시간이라 8시간에서 미리 움직입니다.

**어떻게 불렸는지는 보지 않습니다** (1119 둘째)
    처음에는 「예약(schedule)으로 돈 것이 없으면 실패」로 두었습니다. 그런데
    그러면 손으로 부른 것이 섞일 때 이 그물이 **거짓으로 울립니다.** 그래서
    셈하는 것을 「예약으로 돈 것」에서 **「깨운 것」**으로 바꿉니다. 깨어
    있는지가 알고 싶은 것이지, 누가 불렀는지는 아닙니다.

이 그물도 완전하지 않습니다
    이 일 자체가 깃허브 예약으로 돕니다. 그 예약도 건너뜁니다. 그물이 그물을
    완전히 받치지는 못합니다. 다만 이제 **깨우는 길이 셋**이고(저장소 둘의
    3시간 예약 + 이 그물), 셋이 **따로 등록되어** 있습니다. 셋이 12시간 내내
    같이 비어야 앱이 잠듭니다.

1124 — **여는 일이 한 저장소에 모였습니다**
    이 글은 저장소 하나만 보고 셈하던 때에 쓴 것입니다. 그때는 깨우는 곳이
    셋으로 흩어져 있어서, 제 자취만 보고는 다른 데가 열어 둔 날에도 **비어
    보여 거짓으로 울렸습니다** — 1124 05:33 에 「12.9시간 비었다」며 빨갛게
    끝났는데 진짜 빈틈은 5.0시간이었습니다.

    이제 여는 일(Clock A·B·C·D 와 Watch)이 모두 이 공개 저장소에 있습니다.
    부르는 쪽(net.yml)이 **이 저장소에서 연 판을 모두** 모아 넘겨 주므로,
    여기 셈법이 보는 것이 곧 사이트가 열린 자취입니다.

    앱 저장소(fashionstudio)의 예비 시계는 비공개라 여기서 못 읽습니다.
    그쪽이 열어 둔 날에는 여기가 비어 보여 **쓸데없이 한 번 더 깨울 수**
    있습니다. 그것은 손해가 아닙니다 — 깨우는 것이 목적이니까요.
"""
from __future__ import annotations

import datetime as dt
import json
import os
import sys

깨울_한도_시간 = 8      # 이만큼 비면 **스스로 깨운다**
위험_한도_시간 = 12     # 이만큼 비면 깨우고 **메일까지** 보낸다
#   1124: 10 → 12. 스트림릿이 재우는 선이 12시간인데 10에서 메일을 보내면,
#   앱이 멀쩡히 깨어 있는 날에도 울린다. 두 시계를 합친 이레치 빈틈이 최대
#   10.5시간이라 10 으로는 **거의 날마다 울리는 경보**가 된다. 들을 값어치가
#   있는 것만 남긴다 — 12시간을 넘겼다는 것은 앱이 정말 잠들 수 있었다는 뜻이다.
#   「정말 잠들어 있었나」는 공개 시계의 watch.yml 이 날마다 두 번 직접 열어
#   보고 알린다. 여기 경보는 그 앞을 지키는 미리 알림이다.
자취_한도_시간 = 26     # 이 동안 아무 자취도 없으면 뭔가 단단히 잘못된 것

깨우라 = 10             # 일꾼에게 「지금 깨워라」고 알리는 값


def 읽기(길: str) -> list[dict]:
    with open(길, encoding="utf-8") as f:
        return json.load(f)


def 때(s: str) -> dt.datetime:
    return dt.datetime.fromisoformat(str(s).replace("Z", "+00:00"))


def 일꾼에게(이름: str, 값: str) -> None:
    """GITHUB_OUTPUT 에 적어 다음 단계가 읽게 한다. 없으면 조용히 넘어간다."""
    길 = os.getenv("GITHUB_OUTPUT")
    if not 길:
        return
    try:
        with open(길, "a", encoding="utf-8") as f:
            f.write("%s=%s\n" % (이름, 값))
    except Exception:
        pass


def main() -> int:
    길 = sys.argv[1] if len(sys.argv) > 1 else "runs.json"
    줄 = 읽기(길)
    지금 = dt.datetime.now(dt.timezone.utc)

    성공 = [r for r in 줄 if r.get("c") == "success"]
    if not 성공:
        print("[탈] 성공한 기록이 하나도 없습니다.")
        일꾼에게("wake", "yes")
        일꾼에게("why", "자취가 아예 없습니다")
        return 1

    성공.sort(key=lambda r: 때(r["t"]), reverse=True)
    마지막 = 때(성공[0]["t"])
    지난시간 = (지금 - 마지막).total_seconds() / 3600.0
    최근것 = [r for r in 성공 if (지금 - 때(r["t"])).total_seconds() / 3600.0 <= 자취_한도_시간]

    print("지금(UTC)         : %s" % 지금.strftime("%Y-%m-%d %H:%M"))
    print("마지막으로 깨운 때  : %s  (%.1f시간 전)" % (마지막.strftime("%Y-%m-%d %H:%M"), 지난시간))
    print("지난 %d시간 깨운 수 : %d" % (자취_한도_시간, len(최근것)))

    때들 = [때(r["t"]) for r in 성공[:10]]
    빈틈 = [(때들[i] - 때들[i + 1]).total_seconds() / 3600.0 for i in range(len(때들) - 1)]
    if 빈틈:
        print("최근 빈틈(시간)    : %s" % ", ".join("%.1f" % g for g in 빈틈))
    print("")

    if 지난시간 <= 깨울_한도_시간:
        print("[좋음] %.1f시간 전에 깨웠습니다. 한도 %d시간 안입니다."
              % (지난시간, 깨울_한도_시간))
        일꾼에게("wake", "no")
        return 0

    위험 = 지난시간 > 위험_한도_시간
    까닭 = "마지막으로 깨운 지 %.1f시간 (한도 %d시간)" % (지난시간, 깨울_한도_시간)
    print("[빈틈] %s" % 까닭)
    print("       -> 메일만 보내고 말지 않습니다. **지금 깨웁니다.**")
    if 위험:
        print("[위험] %.1f시간입니다. 스트림릿이 재우는 12시간에 가깝습니다."
              % 지난시간)
        print("       깨운 뒤 **일부러 실패해서** 메일을 보냅니다 — 예약이 거듭")
        print("       건너뛰고 있다는 뜻이고, 그건 사람이 알아야 합니다.")
    if not 최근것:
        print("[탈] 지난 %d시간 동안 깨운 것이 하나도 없습니다." % 자취_한도_시간)

    일꾼에게("wake", "yes")
    일꾼에게("danger", "yes" if 위험 else "no")
    일꾼에게("why", 까닭)
    return 깨우라


if __name__ == "__main__":
    raise SystemExit(main())
